/* Read-only N26 preparation explanations. Sources stay separate from match and roster records. */
(function(){'use strict';
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko)=>`<span data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</span>`;
const source=(kind,id)=>(window.RULES_DATA?.[kind]||[]).find(r=>r.id===id&&r.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26');
const P=(en,ko)=>window.MMRuleTerms?.prose(en,ko,{edition:'n26'})||`<p>${L(en,ko)}</p>`;
function ref(kind,id,en,ko){const row=source(kind,id);return row?`<button type="button" class="btn small" data-rule-term="${E(id)}" data-rule-edition="n26" aria-haspopup="dialog">${L(en||row.name,ko||row.name_ko||row.name)}</button>`:'';}
const sequence='n26-core-prebattle-sequence',select='n26-core-tactics-selection',generate='official-003-core-generating-gang-tactics';
const effectRows=[
 ['bullet-den','Reload allowance','장전',['Once per gang each round, Reload may be a Free action.','각 갱이 라운드마다 한 번 리로드를 프리 행동으로 수행할 수 있습니다.']],
 ['rogue-doc-shop','Recovery assistance','회복 지원',['Assistance adds two Injury dice instead of the usual one.','회복 지원으로 추가하는 부상 주사위가 보통 1개에서 2개로 늘어납니다.']],
 ['mess-shack','Leadership','리더십',['All models gain +1 Leadership.','모든 모델의 리더십 특성이 1 증가합니다.']],
 ['drinking-hole','First-round restriction','첫 라운드 제한',['Ranged weapons cannot be used in round 1.','1라운드에는 원거리 무기를 사용할 수 없습니다.']],
 ['fence-hangout','Side Job reward','사이드 잡 보상',['Completing a Side Job earns the gang an additional D3×10 credits.','사이드 잡을 완수한 갱은 D3×10크레딧을 추가로 얻습니다.']],
 ['bounty-den','Additional objective','추가 부가 목표',['Each player generates one additional Side Job.','각 플레이어가 사이드 잡을 1개 추가 생성합니다.']],
 ['generatorium','Visibility exception','시야 제한 예외',['Visibility (X inches) has no effect.','비지빌리티(X인치) 규칙이 효과를 내지 않습니다.']],
 ['corpse-farm','OOA reward','전투 불능 보상',['Each enemy model taken OOA earns the gang 10 credits.','적 모델을 OOA로 만들 때마다 해당 갱이 10크레딧을 얻습니다.']],
 ['tunnels','Tunnel Warfare','터널 전투',['Apply Tunnel Warfare: no climbing over walls or using stairs or ladders.','터널 워페어를 적용하여 벽 넘기와 계단·사다리 사용이 제한됩니다.']],
 ['tech-bazaar','First-round weapon restriction','첫 라운드 무장 제한',['In round 1, weapons with Blast (3/5 inches) or Template cannot be used.','1라운드에는 블라스트(3/5인치) 또는 템플릿 특성 무기를 사용할 수 없습니다.']],
 ['promethium-cache','Blaze','블레이즈',['The source example changes Blaze (5+) to Blaze (4+). Its wording about increasing X conflicts with that example: agree how to apply it before rolling.','원문 예시는 블레이즈(5+)를 블레이즈(4+)로 바꿉니다. X를 증가시킨다는 본문과 예시 표기가 엇갈리므로 굴림 전에 적용 방식을 확인하세요.']],
 ['collapsed-dome','Dangerous footing','위험한 발판',['A natural 1 on an Agility test causes an additional unsaveable, automatically wounding Str –/AP –/L1 hit.','어질리티 테스트의 자연 1은 자동 운드·세이브 불가인 Str –/AP –/L1 추가 명중을 줍니다.']],
 ['bone-shrine','Shrine objective','슈라인 목표',['The defender places a shrine within 6 inches of the centre; Fighters can control it like an objective to gain XP.','방어자가 중심 6인치 안에 슈라인을 놓습니다. 파이터는 목표처럼 통제하여 XP를 얻을 수 있습니다.']],
 ['mine-workings','Limited visibility','시야 제한',['Apply Visibility (18 inches).','비지빌리티(18인치)를 적용합니다.']],
 ['gambling-den','One reroll','재굴림',['Each player may reroll one die once during the battle.','각 플레이어가 전투 중 주사위 1개를 한 번 재굴림할 수 있습니다.']],
 ['synth-still','Toxin weapon AP','톡신 무기 AP',['Improve AP by 1 for every weapon with Toxin (X+).','톡신(X+) 특성 무기의 AP를 1 향상합니다.']],
 ['old-ruins','Long-range protection','장거리 방어',['Models at the weapon’s long range and not in cover improve their Save characteristic by 1.','무기의 장거리 구간에 있고 엄폐하지 않은 모델은 세이브 특성이 1 향상됩니다.']],
 ['fighting-pit','Close-combat XP','근접전 경험치',['Gain an additional 1 XP for causing an enemy to become Seriously Injured/Damaged or OOA with a close-combat attack.','근접 공격으로 적을 중상·중손상 또는 OOA로 만들면 XP를 1 추가로 얻습니다.']]
];
function effects(){
 if(!source('coreRules',sequence))return '';
 const entries=effectRows.filter(([id])=>source('territories','official-003-territory-'+id)?.rule_data?.battlefield_effect);
 return `<section class="sk-prep-guide" data-sk-effects-guide><div class="sk-guide-heading"><strong>${L('What are battlefield effects?','전장 효과란?')}</strong><span class="sk-guide-tag">${L('Special conditions for this battle','이번 전투의 특수 조건')}</span></div>${P('Rules that change how this battle is played, such as visibility, movement routes, usable weapons or extra objectives. Before choosing tactics and deploying, both players identify which effects apply, who they affect and how long they last.','이번 전투의 시야·이동·무기 사용·추가 목표를 바꾸는 규칙입니다. 택틱 선택·배치 전에 적용 근거를 확인하세요.')}<p class="sk-guide-important">${L('No applicable effect? Confirm “none” together, then mark this step complete. This step does not require a random effect roll.','효과가 없으면 ‘없음’을 확인하고 체크하세요. 무작위 효과를 반드시 뽑는 단계는 아닙니다.')}</p>
 <details class="sk-guide-fold"><summary>${L('Why effects apply · what to announce','왜 발생하나요? · 무엇을 공지하나요?')}</summary><ol class="sk-guide-steps"><li><strong>${L('Find the cause','발생 근거 확인')}</strong>${P('Read the mission and any agreed battlefield rules. In a campaign, a Territory that is the Stake can specify a battlefield effect. Merely owning a Territory does not apply its stake effect to every battle.','미션과 사용하기로 정한 전장 규칙을 확인합니다. 캠페인에서는 내기로 걸린 영토가 전장 효과를 지정하기도 합니다. 단순히 영토를 소유했다는 이유로 그 영토의 내기 전장 효과가 모든 전투에 적용되지는 않습니다.')}</li><li><strong>${L('Announce timing and scope','적용 대상·시점 공지')}</strong>${P('Before tactics and deployment, identify the rule, its targets and its duration. For example, “The Drinking Hole is at stake, so ranged weapons cannot be used in round 1.” This restriction ends after that round.','택틱 선택과 배치 전에 규칙 이름, 적용 대상, 지속 시간을 말합니다. 예: ‘드링킹 홀이 걸린 전투이므로 1라운드에는 양쪽 모두 원거리 무기를 사용할 수 없습니다’라고 확인합니다. 이 제한은 첫 라운드가 지나면 끝납니다.')}</li><li><strong>${L('Standalone skirmish','독립 스커미시에서는')}</strong>${P('This standalone match has no campaign Territory stake. No Territory effect is added automatically from a linked roster. Use the conditions specified for your mission or agreed game; if none apply, there is nothing to add.','이 독립 전투에는 캠페인 영토 내기가 연결되어 있지 않습니다. 연결한 로스터의 영토 효과도 자동으로 추가되지 않습니다. 이번 미션이나 합의한 게임 조건에서 지정한 것만 확인하고, 없다면 효과를 추가할 필요가 없습니다.')}</li></ol><div class="sk-guide-links">${ref('coreRules',sequence,'Preparation order','전투 전 절차')}${ref('coreRules','official-003-core-underhive-battlefield-setup','Battlefield rules','전장 준비 룰')}${ref('coreRules','official-003-core-visibility-and-pitch-black','Visibility & Pitch Black','비지빌리티·피치 블랙')}</div></details>
 <details class="sk-guide-fold" data-sk-effect-examples><summary>${L(`Core Territory effects · ${entries.length} examples`,`기본 영토 전장 효과 ${entries.length}종 보기`)}</summary><p class="sk-guide-caption">${L('These are effects for battles over the named Territory stake. This list is a reference, not a set of effects that all apply to a skirmish. Income boons and recruitment discounts are separate.','아래는 해당 영토를 내기로 건 전투의 효과 목록입니다. 스커미시에 전부 적용하거나 이 목록에서 무조건 하나를 뽑는 방식이 아닙니다. 영토의 정기 수입·모집 할인은 별도 혜택입니다.')}</p><div class="sk-effect-examples">${entries.map(([id,en,ko,text])=>`<article data-sk-effect-source="official-003-territory-${id}"><header>${ref('territories','official-003-territory-'+id)}<small>${L(en,ko)}</small></header>${P(...text)}</article>`).join('')}</div></details></section>`;
}
function tactics(){
 if(!source('coreRules',select)||!source('coreRules',generate))return '';
 return `<div class="sk-prep-guide sk-tactics-explainer" data-sk-tactics-guide><p class="sk-guide-important">${L('For this battle: choose from your gang’s available tactics.','전투 전: 보유·접근 가능한 택틱에서 직접 선택합니다.')}</p>${P('Normally choose 1. The lower-rated gang may choose 1 extra for each full 200-credit difference in the full Gang Ratings. Each selected tactic can be used once per gang in this battle, at the timing written on it.','기본 1개. 전체 갱 레이팅이 낮은 쪽은 차이 200크레딧마다 +1개입니다. 선택한 각 택틱은 적힌 시점에 갱당 전투당 1회 사용합니다.')}
 <details class="sk-guide-fold"><summary>${L('Random or chosen? · acquisition versus battle selection','랜덤인가요, 지정인가요? · 획득과 전투 선택 구분')}</summary><ol class="sk-guide-steps"><li><strong>${L('Acquire tactics → random generation','새 택틱 획득 → 무작위 생성')}</strong>${P('Using the core N26 generation rules, adding a Leader generates 2 tactics; adding or promoting a Champion generates 1; Develop Tactics generates 1. Roll D66 on the permitted generation table and reroll duplicates already owned. Record the results on the gang roster.','N26 기본 생성 규칙에서는 리더를 명단에 추가할 때 2개, 챔피언을 추가·승급할 때 1개, 디벨롭 택틱 행동으로 1개를 생성합니다. 허용된 기본 생성표에서 D66을 굴리고 이미 보유한 결과는 재굴림하여 갱 명단에 기록합니다.')}</li><li><strong>${L('Before each battle → choose available tactics','전투 전 → 보유 목록에서 직접 선택')}</strong>${P('Pick which available tactics to take into this battle, up to the allowance shown above. You do not reroll the entire pool before every battle, and an extra allowance does not grant access to an unowned tactic. Read any specific mission or additional rule that changes selection.','위 선택 한도 안에서 이번 전투에 쓸 보유 택틱을 직접 고릅니다. 매 전투마다 보유 목록 전체를 새로 무작위 생성하지 않습니다. 선택 한도가 늘어도 보유하지 않은 택틱을 새로 획득하는 것은 아닙니다. 선택 방식을 바꾸는 개별 미션·추가 규칙이 있으면 그 지시도 확인하세요.')}</li><li><strong>${L('During battle → resolve the chosen tactic','전투 중 → 선택한 택틱 사용')}</strong>${P('Each selected tactic is once per gang per battle. Selecting the same tactic repeatedly does not create extra uses. A battle’s use does not erase that tactic from the gang’s owned pool.','각 선택 택틱은 갱당 전투당 한 번입니다. 같은 택틱을 중복 선택하여 사용 횟수를 늘리는 방식이 아닙니다. 이번 전투에서 사용했다고 갱의 보유 목록에서 삭제하지 않습니다.')}</li></ol><div class="sk-guide-links">${ref('coreRules',generate,'Acquisition / D66 rules','획득·D66 생성 룰')}${ref('coreRules',select,'Battle selection rules','전투 전 선택 룰')}</div></details>
 <details class="sk-guide-fold" data-sk-tactics-example><summary>${L('Worked example · ratings and available tactics','예시 보기 · 레이팅과 보유 택틱')}</summary>${P('A has Gang Rating 1,000 and B has 1,450. The difference is 450, containing two full 200s: A may select up to 3 tactics (1 + 2), B 1. A 199-credit gap gives no extra; a 200-credit gap gives one extra. Compare the full gangs, not just this battle’s starting crews.','A의 갱 레이팅이 1,000, B가 1,450이면 차이는 450입니다. 200크레딧 두 구간이므로 A는 최대 3개(기본 1 + 추가 2), B는 1개를 선택합니다. 차이가 199면 추가 0개, 200이면 추가 1개입니다. 이번 전투의 시작 크루만이 아니라 전체 갱 레이팅을 비교합니다.')}${P('If A owns Point-blank Shot, Hidden Stash and another tactic, choose from that recorded pool. If the roster has no tactics recorded yet, first check the gang’s founding and acquisition rules. Paper rosters use their written tactics list in the same way.','A가 포인트 블랭크 샷·히든 보관함 등 택틱을 보유했다면 그 기록에서 고릅니다. 아직 택틱 기록이 없다면 갱 창설·획득 규칙부터 확인하세요. 종이 로스터도 기록된 보유 목록을 같은 방식으로 사용합니다.')}</details></div>`;
}
window.MMSkirmishPrepGuide={effects,tactics};
})();
